    function updateClock() {

        const now = new Date();

        clockElement.textContent =
            now.toLocaleTimeString([], {
                hour: "2-digit",
                minute: "2-digit",
                second: "2-digit"
            });

        dateElement.textContent =
            now.toLocaleDateString([], {
                weekday: "long",
                month: "long",
                day: "numeric",
                year: "numeric"
            });
    }

    updateClock();
    setInterval(updateClock, 1000);

    webSearch?.addEventListener("submit", event => {

            event.preventDefault();

            const query = searchInput.value.trim();

            if (!query) return;

            window.open(
                "https://www.google.com/search?q=" +
                encodeURIComponent(query),
                "_blank", "noopener,noreferrer"
            );
        });

    const dungeonWindow =
        document.getElementById("dungeonWindow");

    const dungeonCanvas =
        document.getElementById("dungeonCanvas");

    const dungeonCtx =
        dungeonCanvas?.getContext("2d");

    const TILE = 40;

    const dungeonMaps = [

        [
            "########################",
            "#..........#...........#",
            "#..........#...........#",
            "#......................#",
            "#..####..........####..#",
            "#......................#",
            "#......####..####......#",
            "#......................#",
            "#..####..........####..#",
            "#......................#",
            "#..........#...........#",
            "#..........#.........E.#",
            "#......................#",
            "########################"
        ],

        [
            "########################",
            "#......................#",
            "#..######........####..#",
            "#..#................#..#",
            "#..#....####....####..#",
            "#......................#",
            "###....#........#....###",
            "#......................#",
            "#....####......####....#",
            "#......................#",
            "#..#................#..#",
            "#..######........E##..#",
            "#......................#",
            "########################"
        ],

        [
            "########################",
            "#....#.................#",
            "#....#..######.........#",
            "#.......#..............#",
            "#.......#..####........#",
            "#......................#",
            "#..#####........#####..#",
            "#......................#",
            "#........####..........#",
            "#.......#..............#",
            "#.......#..............#",
            "#.......######......E..#",
            "#......................#",
            "########################"
        ]
    ];

    dungeonMaps.forEach((map,index)=>{dungeonMaps[index]=map.map(row=>row.length===24?row:row.slice(0,-1).padEnd(23,'.')+'#');});
    let dungeonLevel = 1;
    let dungeonCoins = 0;
    let dungeonRunning = false;
    let dungeonPaused = false;
    let dungeonFinished = false;

    let player;
    let dungeonEnemies = [];
    let dungeonChests = [];

    let playerMaxHP = 100;
    let playerHP = 100;
    let playerDamage = 22;
    let playerSpeed = 2.7;

    let attackCooldown = 0;
    let invulnerability = 0;

    const keys = {};

    const dungeonUI = {
        levelText: $("levelText"),
        healthText: $("healthText"),
        healthFill: $("healthFill"),
        coinText: $("coinText"),
        enemyText: $("enemyText"),
        shopCoinText: $("shopCoinText"),
        gameMessage: $("gameMessage")
    };

    function dungeonMap() {
        return dungeonMaps[dungeonLevel - 1];
    }

    function dungeonWall(x, y) {

        const map = dungeonMap();

        if (!map[y] || map[y][x] === undefined) {
            return true;
        }

        return map[y][x] === "#";
    }

    function loadDungeon() {

        player = {
            x: 2.5 * TILE,
            y: 2.5 * TILE,
            direction: "right"
        };

        dungeonEnemies = [];
        dungeonChests = [];

        const map = dungeonMap();

        const enemyLocations = [
            [7,3],
            [17,3],
            [6,10],
            [17,10],
            [12,6],
            [12,9]
        ];

        enemyLocations.forEach((location, index) => {

            const x = location[0];
            const y = location[1];

            if (
                map[y] &&
                map[y][x] &&
                map[y][x] !== "#"
            ) {

                const hp =
                    35 +
                    dungeonLevel * 15;

                dungeonEnemies.push({
                    x: x * TILE + 20,
                    y: y * TILE + 20,
                    hp: index === 5 && dungeonLevel === 3 ? hp*3 : hp,
                    maxHP: index === 5 && dungeonLevel === 3 ? hp*3 : hp,
                    kind: index === 5 && dungeonLevel === 3 ? 'warden' : index % 3 === 0 ? 'brute' : 'slime',
                    waypoint: null,
                    speed: index % 3 === 0 ? .48 + dungeonLevel*.07 : .65 + dungeonLevel * .07,
                    damage: 7 + dungeonLevel * 2,
                    cooldown: index * 15,
                    alive: true
                });
            }
        });

        [
            [4,5],
            [18,5],
            [4,11],
            [18,8]
        ].forEach(([x,y]) => {

            if (map[y] && map[y][x] === ".") {

                dungeonChests.push({
                    x: x * TILE + 20,
                    y: y * TILE + 20,
                    opened: false
                });

            }
        });

        attackCooldown = 0;
        invulnerability = 0;
        dashCooldown = 0; dashFrames = 0; slashFrames = 0; dungeonFX = [];
        clearKeys(); dungeonBackground = null;

        dungeonUI.levelText.textContent =
            `Dungeon ${dungeonLevel} / 3 · ${["The Catacombs","Forgotten Halls","The Warden’s Keep"][dungeonLevel-1]}`;

        updateDungeonHUD();
    }

    function updateDungeonHUD() {

        dungeonUI.healthText.textContent =
            `${Math.max(0, Math.ceil(playerHP))} / ${playerMaxHP}`;

        dungeonUI.healthFill.style.width =
            `${Math.max(0, playerHP / playerMaxHP * 100)}%`;

        dungeonUI.coinText.textContent = dungeonCoins;
        dungeonUI.enemyText.textContent =
            dungeonEnemies.filter(e => e.alive).length;
        dungeonUI.shopCoinText.textContent = dungeonCoins;
        $('dashStatus').textContent = dashCooldown>0 ? (dashCooldown/60).toFixed(1)+'s' : 'Ready';
        document.querySelectorAll('.shop-item').forEach(item=>{const type=item.dataset.shop;item.disabled=dungeonFinished||dungeonCoins<({health:25,maxHealth:60,damage:70,speed:50}[type])||(type==='health'&&playerHP>=playerMaxHP)||(type==='speed'&&playerSpeed>=4.1);});
    }

    function dungeonMessage(text) {

        const message = dungeonUI.gameMessage;

        message.textContent = text;

        clearTimeout(dungeonMessage.timer);

        dungeonMessage.timer =
            setTimeout(() => {

                if (!dungeonFinished) {
                    message.textContent =
                        "Find the exit and defeat the enemies.";
                }

            }, 2200);
    }

    function movePlayer(dx,dy){moveEntity(dungeonMap(),player,dx,dy,10,TILE);}

    function dungeonAttack() {
        if(!dungeonActive() || attackCooldown>0) return;
        attackCooldown=25;slashFrames=12;hubSound('move');
        const angle={right:0,down:Math.PI/2,left:Math.PI,up:-Math.PI/2}[player.direction];
        dungeonEnemies.forEach(enemy=>{
            if(!enemy.alive)return;
            const dx=enemy.x-player.x,dy=enemy.y-player.y,dist=Math.hypot(dx,dy);
            if(dist>65||!lineClear(dungeonMap(),player,enemy)||((dx*Math.cos(angle)+dy*Math.sin(angle))/Math.max(dist,1)<-.25&&dist>28))return;
            enemy.hp-=playerDamage;enemy.flash=8;enemy.waypoint=null;
            moveEntity(dungeonMap(),enemy,dx/Math.max(dist,1)*14,dy/Math.max(dist,1)*14,10,TILE);
            burst(enemy.x,enemy.y,'#ffbc85',8,'−'+playerDamage);hubSound('hit');
            if(enemy.hp<=0){enemy.alive=false;const reward=(enemy.kind==='warden'?100:12+dungeonLevel*4);dungeonCoins+=reward;burst(enemy.x,enemy.y,'#ffd45c',15,'+'+reward);hubSound('coin');dungeonMessage('Monster defeated! +'+reward+' coins');}
        });
        if(dungeonEnemies.every(e=>!e.alive))dungeonMessage('The exit is open. Follow the green portal!');
        updateDungeonHUD();
    }

    function openChest() {
        if(!dungeonActive()) return;

        dungeonChests.forEach(chest => {

            if (chest.opened) return;

            const distance =
                Math.hypot(
                    chest.x - player.x,
                    chest.y - player.y
                );

            if (distance < 55 && lineClear(dungeonMap(),player,chest)) {

                chest.opened = true;
                burst(chest.x,chest.y,"#ffd45c",18);hubSound("coin");

                const reward =
                    25 + dungeonLevel * 10;

                dungeonCoins += reward;

                dungeonMessage(
                    `Treasure found! +${reward} coins`
                );

                updateDungeonHUD();
            }
        });
    }

    function updateDungeon() {
        if(!dungeonActive())return;
        dungeonTick++;
        if(attackCooldown>0)attackCooldown--;if(invulnerability>0)invulnerability--;if(dashCooldown>0)dashCooldown--;if(slashFrames>0)slashFrames--;
        let dx=(keys.d||keys.ArrowRight?1:0)-(keys.a||keys.ArrowLeft?1:0),dy=(keys.s||keys.ArrowDown?1:0)-(keys.w||keys.ArrowUp?1:0);
        if(dx||dy){const length=Math.hypot(dx,dy);dx/=length;dy/=length;player.direction=Math.abs(dx)>Math.abs(dy)?dx>0?'right':'left':dy>0?'down':'up';}
        if(dashFrames>0){dashFrames--;if(!dx&&!dy){const angle={right:0,left:Math.PI,down:Math.PI/2,up:-Math.PI/2}[player.direction];dx=Math.cos(angle);dy=Math.sin(angle);}movePlayer(dx*8,dy*8);burst(player.x,player.y,'#75daee',1);}else movePlayer(dx*playerSpeed,dy*playerSpeed);
        if(keys[' '])dungeonAttack();
        for(const enemy of dungeonEnemies){
            if(!enemy.alive)continue;if(enemy.cooldown>0)enemy.cooldown--;if(enemy.flash>0)enemy.flash--;
            const dx=player.x-enemy.x,dy=player.y-enemy.y,dist=Math.hypot(dx,dy);
            if(dist>25){
                const here=[Math.floor(enemy.x/TILE),Math.floor(enemy.y/TILE)],goal=[Math.floor(player.x/TILE),Math.floor(player.y/TILE)];
                if(here[0]===goal[0]&&here[1]===goal[1])enemy.waypoint={x:player.x,y:player.y};
                if(!enemy.waypoint||Math.hypot(enemy.x-enemy.waypoint.x,enemy.y-enemy.waypoint.y)<2){const route=findPath(dungeonMap(),here,goal);const tile=route[1]||route[0];enemy.waypoint=tile?{x:tile[0]*TILE+20,y:tile[1]*TILE+20}:null;}
                if(enemy.waypoint){const ex=enemy.waypoint.x-enemy.x,ey=enemy.waypoint.y-enemy.y,d=Math.hypot(ex,ey);if(d>0){const beforeX=enemy.x,beforeY=enemy.y;moveEntity(dungeonMap(),enemy,ex/d*Math.min(d,enemy.speed),ey/d*Math.min(d,enemy.speed),10,TILE);if(Math.hypot(enemy.x-beforeX,enemy.y-beforeY)<.01)enemy.waypoint={x:here[0]*TILE+20,y:here[1]*TILE+20};}}
            } else if(enemy.cooldown<=0&&invulnerability<=0&&lineClear(dungeonMap(),enemy,player)){
                playerHP=Math.max(0,playerHP-enemy.damage);enemy.cooldown=65;invulnerability=28;burst(player.x,player.y,'#ff6978',10,'−'+enemy.damage);hubSound('hit');
                if(playerHP<=0){finishDungeon(false);break;}
            }
        }
        dungeonFX.forEach(f=>{f.x+=f.vx;f.y+=f.vy;f.life--;});dungeonFX=dungeonFX.filter(f=>f.life>0);
        updateDungeonHUD();if(!dungeonFinished)checkDungeonExit();
    }

    function checkDungeonExit() {

        const map = dungeonMap();

        let exitX = -1;
        let exitY = -1;

        for (let y = 0; y < map.length; y++) {

            const x = map[y].indexOf("E");

            if (x >= 0) {
                exitX = x;
                exitY = y;
                break;
            }        }

        if (exitX < 0) return;

        const ex = exitX * TILE + 20;
        const ey = exitY * TILE + 20;

        if (
            Math.hypot(
                ex - player.x,
                ey - player.y
            ) < 28
        ) {

            const remaining =
                dungeonEnemies.filter(e => e.alive).length;

            if (remaining > 0) {

                dungeonMessage(
                    `Defeat all ${remaining} monsters first!`
                );

                return;
            }

            if (dungeonLevel < dungeonMaps.length) {

                dungeonCoins += 30;
                dungeonLevel++;
                playerHP=Math.min(playerMaxHP,playerHP+25);hubSound("win");

                dungeonMessage(
                    "Dungeon cleared! +30 coins and 25 HP"
                );

                loadDungeon();

            } else {

                finishDungeon(true);
            }
        }
    }

    function finishDungeon(victory) {

        dungeonRunning = false;
        dungeonFinished = true;
        hubSound(victory ? "win" : "lose");
        $("dungeonShopButton").hidden = true;

        document
            .getElementById("gameOver")
            .classList.add("show");

        document.getElementById("overlayTitle")
            .textContent =
            victory ? "DUNGEON COMPLETE!" : "YOU DIED";

        document.getElementById("overlayText")
            .textContent =
            victory
                ? `You cleared all 3 dungeons with ${dungeonCoins} coins.`
                : `You reached dungeon ${dungeonLevel} with ${dungeonCoins} coins.`;
    }

    function restartDungeon() {

        dungeonLevel = 1;
        dungeonCoins = 0;

        playerMaxHP = 100;
        playerHP = 100;
        playerDamage = 22;
        playerSpeed = 2.7;

        dungeonRunning = true;
        dungeonPaused = false;
        dungeonFinished = false;

        document
            .getElementById("gameOver")
            .classList.remove("show");

        document
            .getElementById("dungeonPaused")
            .classList.remove("show");

        document
            .getElementById("dungeonShop")
            .classList.remove("open");

        loadDungeon();
        updateDungeonPauseButton();
    }

    function toggleDungeonPause() {

        if (!dungeonRunning || dungeonFinished) return;

        if($("dungeonShop").classList.contains("open"))return;
        dungeonPaused = !dungeonPaused;
        clearKeys();

        document
            .getElementById("dungeonPaused")
            .classList.toggle(
                "show",
                dungeonPaused
            );

        updateDungeonPauseButton();
    }

    function updateDungeonPauseButton() {

        document.getElementById("dungeonPause")
            .textContent =
            dungeonPaused
                ? "▶ RESUME"
                : "Ⅱ PAUSE";
    }

    function closeDungeon() {

        if (document.fullscreenElement === dungeonWindow) {
            document.exitFullscreen().catch(() => {});
        }

        dungeonWindow?.classList.remove("open");

        clearKeys();

        document
            .getElementById("dungeonPaused")
            ?.classList.remove("show");

        document
            .getElementById("dungeonShop")
            ?.classList.remove("open");

        updateDungeonPauseButton();
    }

