                    c.fillStyle='#070c1277';c.fillRect(px,py+12,TILE,TILE);
                    c.fillStyle=palette[2];c.fillRect(px+1,py+1,TILE-2,TILE-2);
                    c.fillStyle='#ffffff0d';c.fillRect(px+2,py+2,36,4);
